              <span key={i} className="flex pr-4">
                {showLineNumbers ? (
                  <span aria-hidden="true" className="w-12 shrink-0 pr-4 text-right text-neutral-700 tabular-nums select-none">
                    {i + 1}
                  </span>
                ) : (
                  <span className="w-4 shrink-0" />
